<?php
namespace qqworld_collector\module\collect_filter; use qqworld_collector\lib; class qqworld_collector_parse_infoq_cn_post_content extends lib { var $post_content = array(); public function __construct() { add_filter( 'qqworld-collector-parse-infoq-cn-post-content', array($this, 'filter'), 10, 6 ); } public function filter($item, $source_link, $html, $type, $item_args, $download_args) { $items = json_decode($item, true); if ($items && $items['type'] == 'doc') { $post_contents = $this->parse(array(), $items); if ($post_contents) $item = implode("\r\n", $post_contents); } return $item; } public function parse($results, $items) { switch ($items['type']) { case 'doc': foreach ($items['content'] as $content) { $results = $this->parse($results, $content); } break; case 'paragraph': $results[] = '<p>'; foreach ($items['content'] as $content) { $results = $this->parse($results, $content); } $results[] = '</p>'; break; case 'text': if (isset($items['marks']) && isset($items['marks'][0]) && isset($items['marks'][0]['type']) == 'strong') $text = '<strong>' . $items['text'] . '</strong>'; else $text = $items['text']; $results[] = $text; break; case 'horizontalrule': $results[] = '<hr>'; break; case 'image': $results[] = '<p><img src="'.$items['attrs']['src'].'"></p>'; break; case 'heading': $level = $items['attrs']['level']; $results[] = "<h{$level}>"; foreach ($items['content'] as $content) { $results = $this->parse($results, $content); } $results[] = "</h{$level}>"; break; case 'bulletedlist': $results[] = "<ul>"; foreach ($items['content'] as $content) { $results = $this->parse($results, $content); } $results[] = "</ul>"; break; case 'numberedlist': $start = isset($items['attrs']['start']) ? $items['attrs']['start'] : 1; $results[] = "<ol start=\"{$start}\">"; foreach ($items['content'] as $content) { $results = $this->parse($results, $content); } $results[] = "</ol>"; break; case 'listitem': $results[] = "<li>"; foreach ($items['content'] as $content) { $results = $this->parse($results, $content); } $results[] = "</li>"; break; } return $results; } } new qqworld_collector_parse_infoq_cn_post_content; ?>